import type { APIRoute } from "astro";
import { SITE } from "../config";
import { canonicalUrl } from "../lib/urls";

/**
 * Standard sitemap.xml endpoint for search engines expecting /sitemap.xml.
 * Points to the underlying /sitemap-0.xml generated by @astrojs/sitemap.
 */
export const GET: APIRoute = ({ site }) => {
  const origin = canonicalUrl("/", site ?? SITE.url).replace(/\/+$/, "");
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <sitemap>
    <loc>${origin}/sitemap-0.xml</loc>
  </sitemap>
</sitemapindex>
`;
  return new Response(xml, {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "X-Content-Type-Options": "nosniff",
    },
  });
};
